Keep `useDelayedVisibility` local to `web/app/play/` — it is one small hook over two timers, not a
design-system concern, and `client/` has no other consumer for it.

Create `web/app/play/useDelayedVisibility.ts`:

```ts
'use client';

import { useEffect, useRef, useState } from 'react';

/**
 * True once `active` has been continuously true for `appearAfterMs`, and then stays true for at
 * least `holdForMs`. A download that finishes inside the appear window never shows the bar at all —
 * that is the point: the strobe it prevents is the common case, not the edge case.
 */
export function useDelayedVisibility(
  active: boolean,
  { appearAfterMs, holdForMs }: Readonly<{ appearAfterMs: number; holdForMs: number }>,
): boolean {
  const [visible, setVisible] = useState(false);
  const shownAt = useRef<number | null>(null);

  useEffect(() => {
    if (active) {
      if (shownAt.current !== null) return undefined; // already showing
      // Appear timer: cleared without ever showing if `active` goes false first.
      const appear = setTimeout(() => {
        shownAt.current = Date.now();
        setVisible(true);
      }, appearAfterMs);
      return () => clearTimeout(appear);
    }
    if (shownAt.current === null) return undefined; // never shown — nothing to hold
    // Hold timer: runs ONLY because the bar was actually shown.
    const hold = setTimeout(
      () => {
        shownAt.current = null;
        setVisible(false);
      },
      Math.max(0, holdForMs - (Date.now() - shownAt.current)),
    );
    return () => clearTimeout(hold);
  }, [active, appearAfterMs, holdForMs]);

  return visible;
}
```

